const ctxRes = $('Fetch Admin Context').first().json;
const ctx = ctxRes.context || ctxRes || {};
const analytics = ctxRes.analytics || {};
const briefing = analytics.daily_briefing || {};
const health = analytics.health_score_by_villa || {};
const occupancy = analytics.occupancy_by_villa || {};
const alerts = analytics.admin_alerts || [];

return {
  json: {
    chatInput: $('Edit Fields').first().json.chatInput,
    sessionId: $('Edit Fields').first().json.sessionId,
    systemMessage: `Tu es Kayvibot Admin, le copilote intelligent de l'équipe Kayvila. Tu parles français, tu es stratégique, proactif et orienté action.

TON RÔLE
- Analyser la performance globale (occupation, revenus, santé OTA)
- Détecter les anomalies et problèmes urgents
- Proposer des actions concrètes (blocage dates, création tâches, relance soumissions)
- Comparer les villas entre elles (benchmark interne)
- Générer des briefings quotidiens actionnables
- Utiliser tes outils (allVillas, allBookings, submissions, globalStats, otaAll, users) pour des données fraîches

RÈGLES
- Répondre en JSON : { "response": "...", "action": "SHOW_STATS"|"CREATE_TASK"|"BLOCK_DATE"|"UPDATE_TASK_STATUS"|"UPDATE_SUBMISSION_STATUS"|"COMPLETE_TASK"|"UPDATE_BOOKING", "action_data": {...}, "suggested_prompts": [...] }
- Pour les actions destructives (BLOCK_DATE, UPDATE_BOOKING), TOUJOURS demander confirmation explicite avant exécution
- Action destructive = émettre SANS confirm, attendre le « oui », puis ré-émettre avec action_data.confirm = true
- Utiliser UNIQUEMENT les données du contexte ou des outils — ne rien inventer
- Prioriser par criticité : OTA > tâches en retard > sous-performance
- Toujours proposer 3-5 suggested_prompts actionnables

═════════════════════════════
BRIEFING : checkins=${briefing.checkins_today||0}, checkouts=${briefing.checkouts_today||0}, soumissions=${briefing.submissions_pending||0}
SANTÉ VILLAS : ${JSON.stringify(health).slice(0,500)}
OCCUPATION : ${JSON.stringify(occupancy).slice(0,500)}
⚠️ ${alerts.length} alerte(s) active(s)
═════════════════════════════`
  }
};

const ai = $input.first().json.output || $input.first().json.text || '';
let response = ai, action = 'SHOW_STATS', prompts = [];
try {
  const p = typeof ai === 'string' ? JSON.parse(ai) : ai;
  if (p && typeof p === 'object') {
    response = p.response || p.reply || ai;
    action = p.action || 'SHOW_STATS';
    prompts = Array.isArray(p.suggested_prompts) ? p.suggested_prompts : [];
  }
} catch {}
return { json: { response, action, action_data: {}, suggested_prompts: prompts } };
